// Define a constant for representing an unreachable state or infinity in dynamic programming
const UNREACHABLE_COST = Number.MAX_SAFE_INTEGER; // A large number to signify an impossible sum

/**
 * Calculates the minimum number of specific sequence terms that sum up to a target value.
 * This function processes all terms generated by a specific recurrence relation.
 *
 * @param {number} inputTarget The integer target sum to achieve.
 * @returns {number} The minimum count of terms, or UNREACHABLE_COST if not possible.
 */
function determineMinTermsAll(inputTarget) {
    // Initialize sequence generation variables
    let termCounter = 0;
    let currentSequenceTerm = 1;
    let sumBase = 1;
    let incrementStep = 1;

    // Collection to store generated sequence terms.
    // The first element is conventionally 0 for DP base cases.
    const sequenceTerms = [0];

    // Generate the sequence: a_k = a_{k-1} + b_k, b_k = b_{k-1} + c_k, c_k = c_{k-1} + 1
    // Starting with a_0=1, b_0=1, c_0=1
    while (currentSequenceTerm <= inputTarget) {
        termCounter++;
        sequenceTerms.push(currentSequenceTerm);

        // Update sequence generation parameters for the next iteration
        incrementStep++;
        sumBase += incrementStep;
        currentSequenceTerm += sumBase;
    }

    // Initialize the dynamic programming table
    // dpTable[row][col] stores the minimum terms to sum to 'col' using terms up to 'row'
    // Using a modulo-based row indexing to optimize space (only need 2 rows at a time, but 5 for cleaner modulo arithmetic)
    const dpTable = Array(5).fill(null).map(() => []);

    // Base case: 0 terms needed to sum to 0
    dpTable[0][0] = 0;

    // Initialize all other cells in the first row to UNREACHABLE_COST
    for (let currentSum = 1; currentSum <= inputTarget; currentSum++) {
        dpTable[0][currentSum] = UNREACHABLE_COST;
    }

    // Populate the DP table
    // Outer loop iterates through each available sequence term
    for (let termIndex = 1; termIndex <= termCounter; termIndex++) {
        const currentRowIdx = termIndex % 5;
        let previousRowIdx = currentRowIdx - 1;
        if (previousRowIdx < 0) {
            previousRowIdx = 4; // Wrap around for the modulo 5 indexing
        }

        const currentTermValue = sequenceTerms[termIndex];

        // Inner loop iterates through all possible sums up to inputTarget
        for (let currentSum = 0; currentSum <= inputTarget; currentSum++) {
            if (currentSum < currentTermValue) {
                // If the current sum is less than the current term, we cannot use this term.
                // Inherit the result from the previous term's calculation.
                dpTable[currentRowIdx][currentSum] = dpTable[previousRowIdx][currentSum];
            } else {
                // We have two choices:
                // 1. Don't use the current term: dpTable[previousRowIdx][currentSum]
                // 2. Use the current term: dpTable[currentRowIdx][currentSum - currentTermValue] + 1
                // We take the minimum of these two options.
                const costWithoutTerm = dpTable[previousRowIdx][currentSum];
                const costWithTerm = dpTable[currentRowIdx][currentSum - currentTermValue];

                // Ensure we don't add 1 to an UNREACHABLE_COST, which would cause overflow or incorrect results
                const effectiveCostWithTerm = (costWithTerm === UNREACHABLE_COST) ? UNREACHABLE_COST : costWithTerm + 1;

                dpTable[currentRowIdx][currentSum] = Math.min(costWithoutTerm, effectiveCostWithTerm);
            }
        }
    }

    // The final result is in the cell corresponding to the last term processed and the target sum.
    const finalRow = termCounter % 5;
    const result = dpTable[finalRow][inputTarget];

    // Return the result, or -1 if the target was not reachable
    return (result === UNREACHABLE_COST) ? -1 : result;
}


/**
 * Calculates the minimum number of specific *odd* sequence terms that sum up to a target value.
 * This function processes only odd terms generated by a specific recurrence relation.
 *
 * @param {number} targetSumValue The integer target sum to achieve.
 * @returns {number} The minimum count of terms, or UNREACHABLE_COST if not possible.
 */
function findMinOddTerms(targetSumValue) {
    // Variable to track the count of valid odd terms found
    let oddTermCount = 0;

    // Sequence generation variables, initialized as in the original problem
    let currentVal = 1;
    let currentSum = 1;
    let counter = 1;

    // Array to store only the odd terms from the sequence.
    // Starts with 0 for DP base case.
    const oddSequenceElements = [0];

    // Generate the sequence and filter for odd numbers
    while (currentVal <= targetSumValue) {
        // Check if the current term is odd using a bitwise AND operation
        if (currentVal & 1) { // Equivalent to currentVal % 2 !== 0
            oddTermCount++;
            oddSequenceElements.push(currentVal);
        }

        // Update sequence generation parameters
        counter++;
        currentSum += counter;
        currentVal += currentSum;
    }

    // Initialize the DP table for optimized space (modulo 5 rows)
    const dpMatrix = Array(5).fill(null).map(() => Array(targetSumValue + 1).fill(UNREACHABLE_COST));

    // Base case: 0 terms needed to sum to 0
    dpMatrix[0][0] = 0;

    // Iterate through each odd sequence element
    for (let currentTermIdx = 1; currentTermIdx <= oddTermCount; currentTermIdx++) {
        const rowCurrent = currentTermIdx % 5;
        let rowPrevious = rowCurrent - 1;
        if (rowPrevious < 0) {
            rowPrevious = 4; // Wrap around for circular buffer
        }

        const termMagnitude = oddSequenceElements[currentTermIdx];

        // Iterate through all possible sums
        for (let sumTarget = 0; sumTarget <= targetSumValue; sumTarget++) {
            // Option 1: Don't include the current term
            let costOption1 = dpMatrix[rowPrevious][sumTarget];

            // Option 2: Include the current term, if sumTarget is large enough
            let costOption2 = UNREACHABLE_COST;
            if (sumTarget >= termMagnitude) {
                const prevSumCost = dpMatrix[rowCurrent][sumTarget - termMagnitude];
                if (prevSumCost !== UNREACHABLE_COST) {
                    costOption2 = prevSumCost + 1;
                }
            }
            // Take the minimum cost
            dpMatrix[rowCurrent][sumTarget] = Math.min(costOption1, costOption2);
        }
    }

    // Retrieve the final result from the DP table
    const finalRowIndex = oddTermCount % 5;
    const finalResult = dpMatrix[finalRowIndex][targetSumValue];

    // Return -1 if the target sum is not achievable, otherwise the minimum count
    return (finalResult === UNREACHABLE_COST) ? -1 : finalResult;
}


/**
 * Reads input from stdin, processes each line as a target number,
 * and prints the results from both calculation functions.
 * The processing stops when a target number of 0 is encountered.
 *
 * @param {string} rawInput The raw string data read from the input source.
 */
function processInputData(rawInput) {
    const inputLines = rawInput.split('\n');
    let lineIndex = 0;

    // Loop indefinitely until an explicit break condition (input number is 0)
    while (true) {
        const currentLine = inputLines[lineIndex];

        // Basic validation for empty or invalid lines
        if (!currentLine || currentLine.trim() === '') {
            lineIndex++;
            continue; // Skip empty lines
        }

        const numericInput = parseInt(currentLine.trim(), 10);

        // Check for the termination condition
        if (numericInput === 0) {
            break;
        }

        // Validate if the parsed input is a valid number
        if (isNaN(numericInput) || numericInput < 0) {
            console.error(`Warning: Skipping invalid input line: "${currentLine}"`);
            lineIndex++;
            continue;
        }

        // Execute both problem-solving functions and print their results
        const resultForProblemA = determineMinTermsAll(numericInput);
        const resultForProblemB = findMinOddTerms(numericInput);

        console.log(`${resultForProblemA} ${resultForProblemB}`);
        lineIndex++;
    }
}

// Entry point: Read input from standard I/O and start processing
processInputData(require("fs").readFileSync("/dev/stdin", "utf8"));